\caption{LoRA fine-tuning hyperparameters for the primary 1--1.5B benchmark. Identical across all three model families and all depth levels.}
\label{tab:lora_protocol}
\begin{tabular}{@{}ll@{}}
\toprule
Parameter & Value \\
\midrule
